415	func TestModifyBuyGapRestrictions(t *testing.T) {
416		e := setupModify(t)
417		id := mustBuy(t, e, "A", 5, 10) // 剩余 5、现金占用 50、金额占用 5×10=50
418	
419		// seq3 跨号等待，制造缺口；等待报价不参与判断。
420		mustQuote(t, e, "A", Quote{Seq: 3, Moment: 3, Price: 99}, 0)
421		if st := e.PositionAmountStatus(); st.BuyReserved != 0 {
422			t.Fatalf("未启用金额上限时查询应为零值: %+v", st)
423		}
424	
425		// 剩余量增加 → 拒绝。
426		if err := e.Modify(id, 6, 10); err == nil {
427			t.Fatal("缺口时增加剩余量必须拒绝")
428		}
429		// 现金占用增加（5×11=55>50）→ 拒绝。
430		if err := e.Modify(id, 5, 11); err == nil {
431			t.Fatal("缺口时增加现金占用必须拒绝")
432		}
433		if e.ReservedCash() != 50 {
434			t.Fatalf("拒绝后占用不变: %d", e.ReservedCash())
435		}
436		// 剩余量不增、现金不增：降量允许（金额口径 4×10=40 不增）。
437		recs := len(e.Records())
438		mustModify(t, e, id, 4, 10)
439		if e.ReservedCash() != 40 {
440			t.Fatalf("缺口时降量应允许: reserved=%d", e.ReservedCash())
441		}
442		// 缺口中重复提交当前参数也成功，且不新增记录。
443		if err := e.Modify(id, 4, 10); err != nil {
444			t.Fatalf("缺口时重复提交当前参数应成功: %v", err)
445		}
446		if len(e.Records()) != recs+1 {
447			t.Fatal("重复提交不得新增记录")
448		}
449		// 降价但提量：剩余量增加，拒绝（不能借降价绕开）。
450		if err := e.Modify(id, 5, 1); err == nil {
451			t.Fatal("缺口时不得靠降价增加剩余量")
452		}
453		// 量价都不增：4@8 → 现金 32、金额 4×max(8,10)=40，均不增，允许。
454		mustModify(t, e, id, 4, 8)
455		if e.ReservedCash() != 32 {
456			t.Fatalf("量价不增的修改应允许: reserved=%d", e.ReservedCash())
457		}
