547		mustModify(t, e, sid, 3, 1)
548		if _, err := e.Fill(Trade{TradeID: 2, OrderID: sid, Symbol: "A", Side: Sell, Price: 1, Qty: 3}); err != nil {
549			t.Fatalf("触线后卖单按新参数成交应正常: %v", err)
550		}
551		if e.Position("A") != 7 || e.Cash() != 903 {
552			t.Fatalf("触线后卖出账目错误: pos=%d cash=%d", e.Position("A"), e.Cash())
553		}
554	}
