562		b3 := mustBuy(t, e, "A", 3, 10) // 接受顺序 b1 < b2 < b3
563		// b1 部分成交 2：持仓 2，剩余买单合计 1+3+3=7，总额度占用 9。
564		if _, err := e.Fill(Trade{TradeID: 1, OrderID: b1, Symbol: "A", Side: Buy, Price: 9, Qty: 2}); err != nil {
565			t.Fatal(err)
566		}
567		// 修改中间的 b2（2 股），不改变其接受次序。
