581			t.Fatalf("下一轮应按原次序撤 b2，实际 %v", canceled)
582		}
583		if o, _ := e.Order(b1); o.Status != StatusPartial || o.Remaining() != 1 {
584			t.Fatalf("最早的 b1 应保留: %+v", o)
585		}
586	}
